func New(rate time.Duration, burst int) *Limiter {
	l := &Limiter{tokens: make(chan struct{}, burst)}
	go func() {
		for range time.Tick(rate) {
			select {
			case l.tokens <- struct{}{}:
			default:
			}
		}
	}()
	return l
}

var (
	mu       sync.Mutex
	limiters = map[string]*Limiter{}
)

func limiterFor(clientID string) *Limiter {
	mu.Lock()
	defer mu.Unlock()
	l, ok := limiters[clientID]
	if !ok {
		l = New(5, 10)
		limiters[clientID] = l
	}
	return l
}
